import { pgTable, uuid, varchar, text, timestamp, index, primaryKey } from 'drizzle-orm/pg-core';
export const users = pgTable('users', { id: uuid('id').defaultRandom().primaryKey(), email: varchar('email', { length: 320 }).unique(), username: varchar('username', { length: 64 }).notNull().unique(), displayName: varchar('display_name', { length: 160 }).notNull(), passwordHash: text('password_hash').notNull(), avatarUrl: text('avatar_url'), createdAt: timestamp('created_at', { withTimezone: true }).defaultNow().notNull() });
export const sessions = pgTable('sessions', { id: uuid('id').defaultRandom().primaryKey(), userId: uuid('user_id').notNull().references(() => users.id, { onDelete: 'cascade' }), tokenHash: text('token_hash').notNull().unique(), expiresAt: timestamp('expires_at', { withTimezone: true }).notNull(), createdAt: timestamp('created_at', { withTimezone: true }).defaultNow().notNull() }, table => ({ userIndex: index('sessions_user_idx').on(table.userId) }));
export const posts = pgTable('posts', { id: uuid('id').defaultRandom().primaryKey(), authorId: uuid('author_id').notNull().references(() => users.id, { onDelete: 'cascade' }), body: text('body').notNull().default(''), audience: varchar('audience', { length: 24 }).notNull().default('friends'), createdAt: timestamp('created_at', { withTimezone: true }).defaultNow().notNull() }, table => ({ authorIndex: index('posts_author_idx').on(table.authorId), createdIndex: index('posts_created_idx').on(table.createdAt) }));
export const conversations = pgTable('conversations', { id: uuid('id').defaultRandom().primaryKey(), title: varchar('title', { length: 160 }), createdBy: uuid('created_by').notNull().references(() => users.id), createdAt: timestamp('created_at', { withTimezone: true }).defaultNow().notNull() });
export const conversationMembers = pgTable('conversation_members', { conversationId: uuid('conversation_id').notNull().references(() => conversations.id, { onDelete: 'cascade' }), userId: uuid('user_id').notNull().references(() => users.id, { onDelete: 'cascade' }) }, table => ({ pk: primaryKey({ columns: [table.conversationId, table.userId] }) }));
export const messages = pgTable('messages', { id: uuid('id').defaultRandom().primaryKey(), conversationId: uuid('conversation_id').notNull().references(() => conversations.id, { onDelete: 'cascade' }), senderId: uuid('sender_id').notNull().references(() => users.id), body: text('body').notNull().default(''), sentAt: timestamp('sent_at', { withTimezone: true }).defaultNow().notNull(), readAt: timestamp('read_at', { withTimezone: true }) }, table => ({ conversationIndex: index('messages_conversation_idx').on(table.conversationId, table.sentAt) }));
